/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Disc
 *   Functions: recorded, mbid, synthetic, candidate, incomplete, file, files, membersOf, subset, entryOf, slot,
 *              member, pair, seeded, pick, shuffle, randomGraph, fits, allMatchings, bruteForce, bySlotId
 *   Constants: guard, releases, noIdentifiers, lead, guest, various, standard, deluxe, threeMembers
 * Tests
 *   - audio tracks leave out video and data media, matched case-insensitively with a null format as audio, and keep the Disc Numbers an applied release gives
 *   - rows come in disc and track order with NFC trimmed titles, and a 150-track release or rows over 32 KiB offer no tracklist
 *   - a repeated position, an empty, over-long or invisible-character title, or an out-of-range number gives tracklistInvalid
 *   - pairing respects own Disc and Track Numbers and durations within the tolerance plus legacy precision, and a missing Disc Number matches any disc
 *   - an Album without members has the one empty pairing, and more members than tracks have none
 *   - an unused compatible track or a swap makes the pairing ambiguous, too few compatible tracks make it none, and a forced chain stays unique
 *   - a saved Track Number turns an ambiguous pairing unique, and re-ranking the stored candidates with it re-pairs them without any request
 *   - pairing and forced pairs agree with a brute-force check on 500 small graphs from a seeded generator
 *   - forced pairs with one extra file leave the extra file unpaired, and two files that fit one row are both left unforced
 *   - pairing and forced pairs are invariant under any permutation of slots and members
 *   - a release with more tracks than members matches through a single pairing and reports its pairs, missing tracks, left-out tracks and missing count
 *   - a multi-disc subset of the Blue Archive CD pairs on disc 2 by own numbers, and across discs where the numbers decide
 *   - members with missing Disc Numbers and repeated Track Numbers pair by duration, and stay unverified when durations cannot decide
 *   - an unknown member or paired-track duration leaves the candidate unverified, never preselected but still listed
 *   - fewer audio tracks than members does not match, discloses the track count and names the members no track can pair with
 *   - an empty Album: every candidate is unverified, never preselected, and its missing count equals its audio tracks
 *   - a CD+DVD release counts only audio tracks and discloses the video ones
 *   - a 150-track release is notMatching with tooManyTracks, disclosed and still listed
 *   - the exact-count group is preselected over a matching deluxe group, but not when a left-out release could have exactly as many tracks
 *   - an incomplete candidate with more tracks than members blocks only the only-group rule, and one with fewer audio tracks blocks nothing
 *   - the only matching group of a complete subset comparison is preselected, and two groups are a tie
 *   - a CD edition and its CD+DVD edition with equal Album values and audio tracks form one group, preselected by its exact track count
 *   - members tagged with the Disc Number an import wrote pair on a CD after a video disc, as that disc number
 *   - equal proposals with different row durations or pairings form two groups and a tie, while equal ones share a group
 *   - subset ranking is identical under any permutation of candidates and members, including duplicate candidate keys
 *   - unverified and non-matching candidates list fewer audio tracks than members last, then the fewest extra tracks, then the smallest duration difference
 *   - a legacy whole-second member duration widens the tolerance by its precision in subset mode, as for an import file
 *   - members no audio track can pair with are named only for a release within the expected-tracklist bound
 *   - an iTunes-only candidate never shares a subset group with a MusicBrainz one, and is preselected only when MusicBrainz ruled it out or stayed unavailable
 *   - in subset mode the members' artist names flag a preselection whose credited artist agrees with none, as an import's tags do
 *   - the admission helpers accept an unknown count or at least the member count, and rank the fewest extra tracks first
 *   - the subset assignment gives titles, numbers, durations and track artists only for a single pairing
 *   - track credits: a featuring phrase makes the following entries featured, repeats and placeholders are dropped, and MusicBrainz IDs are kept
 *   - track credits: a placeholder-only credit gives placeholder, and an absent or malformed credit gives missing
 *   - two candidates differing only in a paired track's credit form two groups, while a difference in an unpaired track's credit does not split a group
 *   - stored track credits of an unknown shape propose nothing for their members and group like tracks without credits, never throwing
 * @end-catalog */

/**
 * Subset pairing and ranking without a database or network (lookupSubset.ts and the subset mode of lookupRanking.ts): which
 * release tracks are audio, the expected tracklist rows and their bounds, single, ambiguous and impossible pairings checked
 * against brute force, forced pairs, subset statuses, groups, the exact-count preference, completeness, the admission helpers
 * and per-track artist credits. Recorded releases are parsed by the production parser; everything else is synthetic.
 */
import assert from 'node:assert/strict';
import { readdirSync } from 'node:fs';
import path from 'node:path';
import { after, test } from 'node:test';
import type { LookupArtistCredit, MusicBrainzRelease, MusicBrainzTrack } from '../../src/administration/lookup/lookupContract';
import { itunesRelease } from '../../src/administration/lookup/lookupItunesStage';
import {
    lookupSubsetAssignment, lookupTrackCredit, proposalForRelease, rankLookupCandidates, trackArtistProposal, type LocalFileEvidence, type LookupCandidate, type RankedLookup
} from '../../src/administration/lookup/lookupRanking';
import {
    LOOKUP_EXPECTED_TRACKLIST_BOUNDS, LOOKUP_LEFT_OUT_MEDIUM_FORMATS, expectedTracklistFromRelease, lookupAudioTrackCount, lookupForcedPairs, lookupSubsetPairing,
    lookupSubsetTrackCountPlausible, lookupSurplusRank, lookupUnpairableMembers, releaseAudioTracks, type LookupPairingMember, type LookupPairingSlot, type LookupSubsetPair
} from '../../src/administration/lookup/lookupSubset';
import { parseMusicBrainzRelease } from '../../src/administration/lookup/musicBrainzClient';
import { fixtureRoot, loadLookupFixture } from '../support/metadataLookupFixtures';
import { installNetworkGuard } from '../support/networkGuard';

const guard = installNetworkGuard();
after(() => { guard.restore(); assert.deepEqual(guard.attempts, []); });

/** Every recorded MusicBrainz release, parsed by the production parser. */
const releases = readdirSync(path.join(fixtureRoot, 'musicbrainz')).filter(name => /^release-[0-9a-f-]{36}\.json$/.test(name))
    .map(name => parseMusicBrainzRelease(loadLookupFixture(`musicbrainz/${name}`).exchanges.at(-1)!.body));
const recorded = (prefix: string) => releases.find(value => value.releaseId.startsWith(prefix))!;
const mbid = (n: number) => `0000000c-0000-4000-8000-${String(n).padStart(12, '0')}`;
const noIdentifiers = { releaseId: null, barcode: null, catalogNumber: null };
const lead: LookupArtistCredit = { name: 'Synthetic Lead', joinPhrase: '', artistId: mbid(900), artistName: 'Synthetic Lead' };
const guest: LookupArtistCredit = { name: 'Synthetic Guest', joinPhrase: '', artistId: mbid(901), artistName: 'Synthetic Guest' };
const various: LookupArtistCredit = { name: 'Various Artists', joinPhrase: '', artistId: '89ad4ac3-39f7-470e-963a-56509c546377', artistName: 'Various Artists' };

type Disc = { format?: string | null; lengths: (number | null)[]; titles?: string[]; credits?: MusicBrainzTrack['artistCredit'][] };
/** A synthetic release whose media hold tracks of the given lengths, numbered from 1 per medium. */
const synthetic = (id: number, discs: Disc[], extra: Partial<MusicBrainzRelease> = {}): MusicBrainzRelease => ({
    releaseId: mbid(id), releaseGroupId: null, title: 'Synthetic Album', status: 'Official', artistCredit: [lead], labels: [], barcode: null, barcodeText: null,
    country: null, date: { year: 2020, month: null, day: null }, primaryType: 'Album', secondaryTypes: [], trackCount: discs.reduce((sum, disc) => sum + disc.lengths.length, 0),
    groupFirstReleaseDate: null, frontArtwork: false,
    media: discs.map((disc, medium) => ({ position: medium + 1, format: disc.format === undefined ? 'CD' : disc.format,
        tracks: disc.lengths.map((lengthMs, index) => ({ position: index + 1, number: String(index + 1), title: disc.titles?.[index] ?? `Synthetic ${medium + 1}-${index + 1}`,
            lengthMs, recordingId: mbid(5000 + medium * 100 + index), isrcs: [], ...(disc.credits?.[index] === undefined ? {} : { artistCredit: disc.credits[index] }) })) })),
    ...extra
});
const candidate = (value: MusicBrainzRelease, extra: Partial<LookupCandidate> = {}): LookupCandidate =>
    ({ key: `musicbrainz:${value.releaseId}`, source: 'musicbrainz', releaseId: value.releaseId, summary: null, release: value, ...extra });
const incomplete = (id: number, extra: Partial<LookupCandidate> = {}): LookupCandidate =>
    ({ key: `musicbrainz:${mbid(id)}`, source: 'musicbrainz', releaseId: mbid(id), summary: null, release: null, ...extra });
const file = (index: number, durationMs: number | null, extra: Partial<LocalFileEvidence> = {}): LocalFileEvidence => ({ slotId: `slot-${String(index).padStart(2, '0')}`,
    order: index, durationMs, durationPrecisionMs: 0, discNumber: null, trackNumber: null, artistTags: [], identifiers: noIdentifiers, ...extra });
const files = (lengths: (number | null)[]) => lengths.map((durationMs, index) => file(index, durationMs));
/** Members taken from a release's own tracks: their durations and, when asked, their audio Disc and Track Numbers. */
const membersOf = (value: MusicBrainzRelease, numbered: boolean) => releaseAudioTracks(value).tracks.map((track, index) =>
    file(index, track.durationMs, numbered ? { discNumber: track.discNumber, trackNumber: track.trackNumber } : {}));
const subset = (candidates: readonly LookupCandidate[], members: readonly LocalFileEvidence[], options: Parameters<typeof rankLookupCandidates>[2] = {}) =>
    rankLookupCandidates(candidates, members, { comparison: 'subset', ...options });
const entryOf = (ranked: RankedLookup, value: MusicBrainzRelease) => ranked.candidates.find(entry => entry.releaseId === value.releaseId)!;
const slot = (discNumber: number, trackNumber: number, durationMs: number | null): LookupPairingSlot => ({ discNumber, trackNumber, durationMs });
const member = (slotId: string, discNumber: number | null, trackNumber: number | null, durationMs: number | null, durationPrecisionMs: 0 | 1000 = 0): LookupPairingMember =>
    ({ slotId, discNumber, trackNumber, durationMs, durationPrecisionMs });
const pair = (slotId: string, discNumber: number, trackNumber: number): LookupSubsetPair => ({ slotId, discNumber, trackNumber });

/** The standard edition and its deluxe edition, two more tracks, both matching three members by duration alone. */
const standard = synthetic(1, [{ lengths: [200_000, 230_000, 260_000] }]);
const deluxe = synthetic(2, [{ lengths: [200_000, 230_000, 260_000, 290_000, 320_000] }]);
const threeMembers = files([200_000, 230_000, 260_000]);

test('audio tracks leave out video and data media, matched case-insensitively with a null format as audio, and keep the Disc Numbers an applied release gives', () => {
    const summary = (value: Pick<MusicBrainzRelease, 'media'>) => ((audio) => ({ tracks: audio.tracks.map(track => [track.discNumber, track.trackNumber, track.durationMs]),
        leftOutTracks: audio.leftOutTracks, discCount: audio.discCount }))(releaseAudioTracks(value));
    const cdDvd = synthetic(10, [{ lengths: [200_000, 0] }, { format: 'DVD-Video', lengths: [300_000, 310_000, 320_000] }]);
    assert.deepEqual(summary(cdDvd), { tracks: [[1, 1, 200_000], [1, 2, null]], leftOutTracks: 3, discCount: 1 });
    const dvdCd = synthetic(11, [{ format: ' dvd-VIDEO ', lengths: [300_000] }, { format: 'Blu-ray', lengths: [] }, { format: null, lengths: [200_000, 210_000] }, { lengths: [190_000] }]);
    assert.deepEqual(summary(dvdCd), { tracks: [[2, 1, 200_000], [2, 2, 210_000], [3, 1, 190_000]], leftOutTracks: 1, discCount: 2 },
        'a CD after a DVD-Video with a tracklist is Disc 2, and a medium without tracks is no disc');
    // The numbering is the one an import of the release writes (proposalForRelease): media with tracks, whatever their format.
    assert.deepEqual(releaseAudioTracks(dvdCd).tracks.map(track => [track.discNumber, track.trackNumber]),
        proposalForRelease(dvdCd).tracks.filter(track => track.discNumber > 1).map(track => [track.discNumber, track.trackNumber]));
    // Pregap and data tracks a medium lists apart count as left out, also on a medium without tracks, which stays no disc.
    const hidden = synthetic(14, [{ lengths: [] }, { lengths: [200_000] }, { format: 'DVD-Video', lengths: [300_000] }]);
    Object.assign(hidden.media[0], { hiddenTracks: 1 }); Object.assign(hidden.media[1], { hiddenTracks: 2 }); Object.assign(hidden.media[2], { hiddenTracks: 1 });
    assert.deepEqual(summary(hidden), { tracks: [[1, 1, 200_000]], leftOutTracks: 5, discCount: 1 });
    for (const count of [0, -1, 1.5, '2', null]) {
        Object.assign(hidden.media[1], { hiddenTracks: count });
        assert.equal(releaseAudioTracks(hidden).leftOutTracks, 3, `a stored count of ${JSON.stringify(count)} counts nothing`);
    }
    // Every listed format is left out whatever its case; audio formats, including DVD-Audio and SACD layers, are kept.
    for (const format of LOOKUP_LEFT_OUT_MEDIUM_FORMATS) assert.equal(releaseAudioTracks(synthetic(12, [{ format: format.toUpperCase(), lengths: [1000] }])).leftOutTracks, 1, format);
    for (const format of ['CD', 'Digital Media', 'DVD-Audio', 'Hybrid SACD (CD layer)', '12" Vinyl', 'DualDisc', null]) {
        assert.equal(releaseAudioTracks(synthetic(12, [{ format, lengths: [1000] }])).tracks.length, 1, String(format));
    }
    // The recorded live release: its Blu-ray, medium 1, is left out and its two CDs keep Disc Numbers 2 and 3.
    const live = releaseAudioTracks(recorded('999e900d'));
    assert.deepEqual([live.tracks.length, live.leftOutTracks, live.discCount, live.tracks[0].discNumber, live.tracks[11].discNumber, live.tracks[11].trackNumber], [25, 25, 2, 2, 3, 1]);
    // A pregap or malformed position is left out and stored shapes from another release never throw; tracks sort by position.
    const odd = synthetic(13, [{ lengths: [100_000, 200_000, 300_000, 400_000] }]);
    odd.media[0].tracks = [odd.media[0].tracks[2], { ...odd.media[0].tracks[0], position: 0 }, { ...odd.media[0].tracks[1], position: 1.5 }, odd.media[0].tracks[3], null as never];
    odd.media[0].tracks[0] = { ...odd.media[0].tracks[0], position: 2 };
    assert.deepEqual(summary(odd), { tracks: [[1, 2, 300_000], [1, 4, 400_000]], leftOutTracks: 3, discCount: 1 });
    for (const broken of [{ media: 'x' }, { media: [null, { format: 'CD', tracks: 'x' }, { format: 7, tracks: [] }] }, null, {}]) {
        assert.deepEqual(summary(broken as never), { tracks: [], leftOutTracks: 0, discCount: 0 }, JSON.stringify(broken));
    }
    assert.deepEqual(summary({ media: [{ position: 1, format: { name: 'CD' } as never, tracks: [{ position: 1, lengthMs: Number.NaN } as never, { position: 2, lengthMs: 200_000.5 } as never] }] }),
        { tracks: [[1, 1, null], [1, 2, null]], leftOutTracks: 0, discCount: 1 }, 'a non-string format is audio, and a non-finite or fractional duration unknown');
});

test('rows come in disc and track order with NFC trimmed titles, and a 150-track release or rows over 32 KiB offer no tracklist', () => {
    const composed = String.fromCodePoint(0xe9), decomposed = String.fromCodePoint(0x65, 0x301);
    const value = synthetic(20, [{ format: 'DVD-Video', lengths: [1] }, { lengths: [200_000, null], titles: [`  Caf${decomposed} `, 'Second'] }, { lengths: [180_000.5] }]);
    assert.deepEqual(expectedTracklistFromRelease(value), { rows: [
        { discNumber: 2, trackNumber: 1, title: `Caf${composed}`, durationMs: 200_000 }, { discNumber: 2, trackNumber: 2, title: 'Second', durationMs: null },
        { discNumber: 3, trackNumber: 1, title: 'Synthetic 3-1', durationMs: null }], leftOutTracks: 1 }, 'a stored fractional duration is unknown in the rows');
    // A release without audio tracks offers no rows at all, so nothing could store an empty tracklist.
    assert.deepEqual(expectedTracklistFromRelease(synthetic(21, [])), { reason: 'trackCount', audioTrackCount: 0, leftOutTracks: 0 });
    assert.deepEqual(expectedTracklistFromRelease(synthetic(23, [{ format: 'DVD-Video', lengths: [1, 2] }])), { reason: 'trackCount', audioTrackCount: 0, leftOutTracks: 2 });
    const long = (count: number, title = 'T') => synthetic(22, [{ lengths: Array.from({ length: count }, () => 200_000), titles: Array.from({ length: count }, () => title) }]);
    assert.equal((expectedTracklistFromRelease(long(100)) as { rows: unknown[] }).rows.length, 100);
    assert.deepEqual(expectedTracklistFromRelease(long(101)), { reason: 'tooManyTracks', audioTrackCount: 101, leftOutTracks: 0 });
    assert.deepEqual(expectedTracklistFromRelease(long(150)), { reason: 'tooManyTracks', audioTrackCount: 150, leftOutTracks: 0 });
    // Bytes count the UTF-8 rows: 100 rows of 250 ASCII characters fit, 100 rows of 100 three-byte characters do not.
    const fitting = expectedTracklistFromRelease(long(100, 'x'.repeat(250))) as { rows: unknown[] };
    assert.ok(Buffer.byteLength(JSON.stringify(fitting.rows)) <= LOOKUP_EXPECTED_TRACKLIST_BOUNDS.bytes);
    const wide = long(100, String.fromCodePoint(0x3042).repeat(100));
    const wideRows = wide.media[0].tracks.map(track => ({ discNumber: 1, trackNumber: track.position, title: track.title, durationMs: track.lengthMs }));
    assert.ok(Buffer.byteLength(JSON.stringify(wideRows)) > LOOKUP_EXPECTED_TRACKLIST_BOUNDS.bytes);
    assert.deepEqual(expectedTracklistFromRelease(wide), { reason: 'tooManyTracks', audioTrackCount: 100, leftOutTracks: 0 });
});

test('a repeated position, an empty, over-long or invisible-character title, or an out-of-range number gives tracklistInvalid', () => {
    const titled = (title: unknown) => synthetic(30, [{ lengths: [200_000, 210_000] }], {}).media[0].tracks.map((track, index) => index ? track : { ...track, title: title as string });
    const invalidOf = (tracks: MusicBrainzTrack[]) => expectedTracklistFromRelease({ media: [{ position: 1, format: 'CD', tracks }] });
    assert.ok('rows' in invalidOf(titled('x'.repeat(300))));
    assert.ok('rows' in invalidOf(titled(` ${'x'.repeat(300)} `)), 'the bound applies after trimming');
    for (const title of ['', '   ', 'x'.repeat(301), `a${String.fromCharCode(0x200b)}b`, `a${String.fromCharCode(7)}`, `a${String.fromCharCode(0xd800)}`, 7, null]) {
        assert.deepEqual(invalidOf(titled(title)), { reason: 'tracklistInvalid', audioTrackCount: 2, leftOutTracks: 0 }, JSON.stringify(title));
    }
    // Such a release can neither match nor be preselected, even with exactly as many tracks as members.
    const blank = synthetic(33, [{ lengths: [200_000, 210_000], titles: ['First', '   '] }]), ranked = subset([candidate(blank)], files([200_000, 210_000]));
    assert.deepEqual([entryOf(ranked, blank).status, entryOf(ranked, blank).comparison!.differences, ranked.preselection], ['notMatching', ['tracklistInvalid'], null]);
    const repeated = synthetic(31, [{ lengths: [200_000, 210_000] }]);
    repeated.media[0].tracks[1].position = 1;
    assert.deepEqual(expectedTracklistFromRelease(repeated), { reason: 'tracklistInvalid', audioTrackCount: 2, leftOutTracks: 0 });
    const far = synthetic(32, [{ lengths: [200_000] }]);
    far.media[0].tracks[0].position = 10_000;
    assert.deepEqual(expectedTracklistFromRelease(far), { reason: 'tracklistInvalid', audioTrackCount: 1, leftOutTracks: 0 });
    far.media[0].tracks[0].position = 9999;
    assert.ok('rows' in expectedTracklistFromRelease(far));
});

test('pairing respects own Disc and Track Numbers and durations within the tolerance plus legacy precision, and a missing Disc Number matches any disc', () => {
    const slots = [slot(1, 1, 200_000), slot(1, 2, 250_000), slot(2, 1, 200_000)];
    const kind = (...members: LookupPairingMember[]) => lookupSubsetPairing(slots, members);
    assert.deepEqual(kind(member('a', 2, 1, 200_000)), { kind: 'unique', pairs: [pair('a', 2, 1)] });
    assert.deepEqual(kind(member('a', null, 2, 253_000)), { kind: 'unique', pairs: [pair('a', 1, 2)] });
    assert.deepEqual(kind(member('a', null, 2, 253_001)), { kind: 'none' });
    assert.deepEqual(kind(member('a', null, 2, 254_000, 1000)), { kind: 'unique', pairs: [pair('a', 1, 2)] });
    assert.deepEqual(kind(member('a', null, 2, 245_999, 1000)), { kind: 'none' });
    assert.deepEqual(kind(member('a', 1, 1, null)), { kind: 'unique', pairs: [pair('a', 1, 1)] }, 'an unknown duration constrains nothing');
    assert.deepEqual(lookupSubsetPairing([slot(1, 1, null)], [member('a', null, null, 999_000)]), { kind: 'unique', pairs: [pair('a', 1, 1)] });
    assert.deepEqual(kind(member('a', null, 1, 200_000)), { kind: 'ambiguous' }, 'a missing Disc Number matches Track 1 of both discs');
    assert.deepEqual(kind(member('a', 3, null, null)), { kind: 'none' });
    assert.deepEqual(lookupSubsetPairing(slots, [member('a', null, 2, 251_000)], 500), { kind: 'none' }, 'the tolerance is a parameter');
    // A number that is no positive safe integer is missing, and a non-positive duration unknown.
    assert.deepEqual(kind(member('a', 0, 2.5, 250_000)), { kind: 'unique', pairs: [pair('a', 1, 2)] });
    assert.deepEqual(kind(member('a', 2, 1, -5)), { kind: 'unique', pairs: [pair('a', 2, 1)] });
    assert.deepEqual(kind(member('a', null, 1, 0)), { kind: 'ambiguous' });
    // A slot without a valid position takes no member.
    assert.deepEqual(lookupSubsetPairing([slot(0, 1, 200_000), { discNumber: 1, trackNumber: null, durationMs: 200_000 } as never], [member('a', null, null, null)]), { kind: 'none' });
});

test('an Album without members has the one empty pairing, and more members than tracks have none', () => {
    assert.deepEqual(lookupSubsetPairing([slot(1, 1, 200_000)], []), { kind: 'unique', pairs: [] });
    assert.deepEqual(lookupSubsetPairing([], []), { kind: 'unique', pairs: [] });
    assert.deepEqual(lookupSubsetPairing([slot(1, 1, null)], [member('a', null, null, null), member('b', null, null, null)]), { kind: 'none' });
    assert.deepEqual(lookupSubsetPairing('x' as never, 'y' as never), { kind: 'unique', pairs: [] }, 'stored shapes never throw');
});

test('an unused compatible track or a swap makes the pairing ambiguous, too few compatible tracks make it none, and a forced chain stays unique', () => {
    assert.deepEqual(lookupSubsetPairing([slot(1, 1, 200_000), slot(1, 2, 200_000)], [member('a', null, null, 200_000)]), { kind: 'ambiguous' });
    assert.deepEqual(lookupSubsetPairing([slot(1, 1, 200_000), slot(1, 2, 201_000)], [member('a', null, null, 200_000), member('b', null, null, 201_000)]), { kind: 'ambiguous' });
    assert.deepEqual(lookupSubsetPairing([slot(1, 1, 200_000), slot(1, 2, 300_000)], [member('a', null, null, 200_000), member('b', null, null, 201_000)]), { kind: 'none' });
    // a may take either of the first two tracks, but b can only take the second: the one pairing gives a the first.
    assert.deepEqual(lookupSubsetPairing([slot(1, 1, 200_000), slot(1, 2, 205_000), slot(1, 3, 210_000)],
        [member('a', null, null, 202_500), member('b', null, null, 205_000), member('c', null, null, 210_000)]),
    { kind: 'unique', pairs: [pair('a', 1, 1), pair('b', 1, 2), pair('c', 1, 3)] });
});

test('a saved Track Number turns an ambiguous pairing unique, and re-ranking the stored candidates with it re-pairs them without any request', () => {
    const slots = [slot(1, 1, 200_000), slot(1, 2, 200_500)];
    assert.deepEqual(lookupSubsetPairing(slots, [member('a', null, null, 200_000), member('b', null, null, 200_400)]), { kind: 'ambiguous' });
    assert.deepEqual(lookupSubsetPairing(slots, [member('a', null, 2, 200_000), member('b', null, null, 200_400)]), { kind: 'unique', pairs: [pair('a', 1, 2), pair('b', 1, 1)] });
    const close = synthetic(40, [{ lengths: [200_000, 200_500, 290_000] }]);
    const stored = Object.freeze([Object.freeze(candidate(close))]);
    const before = subset(stored, [file(0, 200_000), file(1, 200_400)]);
    assert.deepEqual([entryOf(before, close).status, entryOf(before, close).comparison!.subset!.pairing, before.preselection], ['unverified', 'ambiguous', null]);
    const saved = subset(stored, [file(0, 200_000, { trackNumber: 2 }), file(1, 200_400)]);
    assert.deepEqual([entryOf(saved, close).status, entryOf(saved, close).comparison!.subset!.pairs, saved.preselection?.basis],
        ['matching', [pair('slot-00', 1, 2), pair('slot-01', 1, 1)], 'onlyMatchingGroup']);
    assert.deepEqual(guard.attempts, []);
});

/** A seeded generator (mulberry32), so the random graphs are the same on every run. */
const seeded = (seed: number) => () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let value = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    value = (value + Math.imul(value ^ (value >>> 7), 61 | value)) ^ value;
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
};
const pick = <T>(random: () => number, values: readonly T[]): T => values[Math.floor(random() * values.length)];
const shuffle = <T>(random: () => number, values: readonly T[]): T[] => {
    const copy = [...values];
    for (let index = copy.length - 1; index > 0; index--) { const other = Math.floor(random() * (index + 1)); [copy[index], copy[other]] = [copy[other], copy[index]]; }
    return copy;
};
/** A small random graph: at most six slots at distinct positions and five members with random own numbers, durations and precision. */
const randomGraph = (random: () => number) => {
    const positions = shuffle(random, [[1, 1], [1, 2], [1, 3], [2, 1], [2, 2], [2, 3]]).slice(0, Math.floor(random() * 7));
    const slots = positions.map(([disc, track]) => slot(disc, track, pick(random, [null, 200_000, 202_000, 204_000, 207_000])));
    const members = Array.from({ length: Math.floor(random() * 6) }, (_unused, index) => member(`m${index}`, pick(random, [null, null, 1, 2]), pick(random, [null, null, 1, 2, 3]),
        pick(random, [null, 200_000, 203_000, 206_000]), pick(random, [0, 0, 1000] as const)));
    return { slots, members };
};
const fits = (one: LookupPairingMember, place: LookupPairingSlot) => (one.discNumber === null || one.discNumber === place.discNumber)
    && (one.trackNumber === null || one.trackNumber === place.trackNumber)
    && (one.durationMs === null || place.durationMs === null || Math.abs(one.durationMs - place.durationMs) <= 3000 + one.durationPrecisionMs);
/** Every matching, each member taking a distinct compatible slot index or -1, by exhaustive search. */
const allMatchings = (slots: LookupPairingSlot[], members: LookupPairingMember[]) => {
    const found: number[][] = [];
    const walk = (index: number, chosen: number[]) => {
        if (index === members.length) { found.push(chosen); return; }
        walk(index + 1, [...chosen, -1]);
        slots.forEach((place, slotIndex) => { if (!chosen.includes(slotIndex) && fits(members[index], place)) walk(index + 1, [...chosen, slotIndex]); });
    };
    walk(0, []);
    return found;
};
const bruteForce = (slots: LookupPairingSlot[], members: LookupPairingMember[]) => {
    const matchings = allMatchings(slots, members), complete = matchings.filter(matching => matching.every(index => index >= 0));
    const pairsOf = (matching: number[]) => matching.flatMap((index, at) => index < 0 ? [] : [pair(members[at].slotId, slots[index].discNumber, slots[index].trackNumber)]);
    const pairing = complete.length === 1 ? { kind: 'unique', pairs: pairsOf(complete[0]) } : { kind: complete.length ? 'ambiguous' : 'none' };
    const size = (matching: number[]) => matching.filter(index => index >= 0).length, largest = Math.max(...matchings.map(size));
    const maximum = matchings.filter(matching => size(matching) === largest);
    const forced = members.flatMap((one, at) => maximum[0][at] >= 0 && maximum.every(matching => matching[at] === maximum[0][at])
        ? [pair(one.slotId, slots[maximum[0][at]].discNumber, slots[maximum[0][at]].trackNumber)] : []);
    return { pairing, forced };
};
const bySlotId = (pairs: LookupSubsetPair[]) => [...pairs].sort((left, right) => left.slotId < right.slotId ? -1 : left.slotId > right.slotId ? 1 : 0);

test('pairing and forced pairs agree with a brute-force check on 500 small graphs from a seeded generator', () => {
    const random = seeded(20261021), kinds = new Map<string, number>();
    let forcedSeen = 0, partlyForced = 0;
    for (let round = 0; round < 500; round++) {
        const { slots, members } = randomGraph(random), expected = bruteForce(slots, members), label = JSON.stringify({ slots, members });
        const pairing = lookupSubsetPairing(slots, members), forced = lookupForcedPairs(slots, members);
        assert.deepEqual(pairing, expected.pairing, label);
        assert.deepEqual(forced, expected.forced, label);
        if (pairing.kind === 'unique') assert.deepEqual(forced, pairing.pairs, `a single pairing is forced whole: ${label}`);
        kinds.set(pairing.kind, (kinds.get(pairing.kind) ?? 0) + 1);
        if (forced.length) forcedSeen++;
        if (pairing.kind !== 'unique' && forced.length) partlyForced++;
    }
    // The generator reaches every outcome often enough for the comparison to mean something.
    for (const kind of ['unique', 'ambiguous', 'none']) assert.ok((kinds.get(kind) ?? 0) >= 50, `${kind}: ${kinds.get(kind)}`);
    assert.ok(forcedSeen >= 100 && partlyForced >= 20, `${forcedSeen} ${partlyForced}`);
});

test('forced pairs with one extra file leave the extra file unpaired, and two files that fit one row are both left unforced', () => {
    const rows = [slot(1, 1, 200_000), slot(1, 2, 250_000)];
    assert.deepEqual(lookupForcedPairs(rows, [member('a', null, null, 200_000), member('b', null, null, 250_000), member('extra', null, null, 400_000)]),
        [pair('a', 1, 1), pair('b', 1, 2)]);
    assert.deepEqual(lookupForcedPairs(rows, [member('a', null, null, 200_000), member('b', null, null, 201_000)]), []);
    assert.deepEqual(lookupForcedPairs(rows, [member('a', null, null, 200_000), member('b', null, null, 201_000), member('c', null, null, 250_000)]), [pair('c', 1, 2)]);
    assert.deepEqual(lookupForcedPairs([], [member('a', null, null, null)]), []);
    assert.deepEqual(lookupForcedPairs(rows, []), []);
});

test('pairing and forced pairs are invariant under any permutation of slots and members', () => {
    const random = seeded(7);
    for (let round = 0; round < 200; round++) {
        const { slots, members } = randomGraph(random), label = JSON.stringify({ slots, members });
        const pairing = lookupSubsetPairing(slots, members), forced = lookupForcedPairs(slots, members);
        const permutedSlots = shuffle(random, slots), permutedMembers = shuffle(random, members);
        const again = lookupSubsetPairing(permutedSlots, permutedMembers);
        assert.equal(again.kind, pairing.kind, label);
        if (again.kind === 'unique' && pairing.kind === 'unique') assert.deepEqual(bySlotId(again.pairs), bySlotId(pairing.pairs), label);
        assert.deepEqual(bySlotId(lookupForcedPairs(permutedSlots, permutedMembers)), bySlotId(forced), label);
    }
});

