    const tie = subset([candidate(deluxe), candidate(other)], threeMembers);
    assert.deepEqual([tie.groups.length, tie.preselection], [2, null]);
    assert.equal(subset([candidate(deluxe)], threeMembers, { searchComplete: false }).preselection, null, 'a partial comparison offers it without a preselection');
    // An identifier rule still runs first in subset mode.
    const tagged = subset([candidate(deluxe), candidate(other)], threeMembers.map(one => ({ ...one, identifiers: { ...noIdentifiers, releaseId: other.releaseId } })));
