test('subset ranking is identical under any permutation of candidates and members, including duplicate candidate keys', () => {
    const cd = recorded('8baecda4');
    const fourTracks = synthetic(120, [{ lengths: [200_000, 230_000, 260_000, 291_000] }]);
    const input = [candidate(deluxe), candidate(standard), candidate(cd), candidate(fourTracks), incomplete(121, { reportedTrackCount: 5 }), { ...candidate(standard), release: null }];
    const members = [...threeMembers, file(3, 290_000, { trackNumber: 4 })];
    const expected = subset(input, members);
    const random = seeded(99);
    for (let round = 0; round < 10; round++) {
        const shuffled = shuffle(random, [...input, ...input.slice(0, 2)]);
        assert.deepEqual(subset(shuffled, shuffle(random, members)), expected);
    }
    assert.deepEqual([expected.groups.length, expected.preselection?.candidateKey, expected.preselection?.basis, expected.completeness],
        [2, candidate(fourTracks).key, 'exactTrackCount', { exact: true, subset: false }]);
});

test('unverified and non-matching candidates list fewer audio tracks than members last, then the fewest extra tracks, then the smallest duration difference', () => {
    // The third member has no duration, so every candidate stays unverified and is ordered rather than grouped.
    const members = [file(0, 200_000, { trackNumber: 1 }), file(1, 230_000, { trackNumber: 2 }), file(2, null, { trackNumber: 3 })];
    const close = synthetic(171, [{ lengths: [200_000, 230_000, 260_000, 290_000] }]);
    const far = synthetic(170, [{ lengths: [202_000, 232_000, 260_000, 290_000] }]);
    const longer = synthetic(169, [{ lengths: [200_000, 230_000, 260_000, 290_000, 320_000] }]);
    const short = synthetic(168, [{ lengths: [200_000, 230_000] }]);
    const ranked = subset([candidate(short), candidate(longer), candidate(far), candidate(close)], members);
    assert.deepEqual(ranked.candidates.map(entry => [entry.releaseId, entry.status]),
        [[close.releaseId, 'unverified'], [far.releaseId, 'unverified'], [longer.releaseId, 'unverified'], [short.releaseId, 'notMatching']]);
    assert.deepEqual(entryOf(ranked, far).comparison!.files.map(row => row.deltaMs), [-2000, -2000, null]);
});

test('a legacy whole-second member duration widens the tolerance by its precision in subset mode, as for an import file', () => {
    const legacy = [file(0, 203_800, { durationPrecisionMs: 1000 }), file(1, 230_000), file(2, 260_000)];
    const entry = entryOf(subset([candidate(standard)], legacy), standard);
    assert.deepEqual([entry.status, entry.comparison!.files[0]], ['matching', { slotId: 'slot-00', localMs: 203_800, candidateMs: 200_000, deltaMs: 3800, withinTolerance: true }]);
    // The same duration at millisecond precision fits no track.
    const precise = entryOf(subset([candidate(standard)], [file(0, 203_800), ...legacy.slice(1)]), standard);
    assert.deepEqual([precise.status, precise.comparison!.differences, precise.comparison!.subset!.unpairableSlotIds], ['notMatching', ['pairing'], ['slot-00']]);
    // A stored member without a valid precision counts as millisecond precision, and a duration of 0 as unknown, in pairing, file
    // rows and the disclosure alike.
    const odd = [file(0, 201_500, { durationPrecisionMs: undefined as never }), file(1, 0), file(2, 260_000)];
    const ranked = subset([candidate(standard)], odd), oddEntry = entryOf(ranked, standard);
    assert.deepEqual([oddEntry.status, oddEntry.comparison!.subset!.pairing, oddEntry.comparison!.files.map(row => [row.localMs, row.withinTolerance])],
        ['unverified', 'unique', [[201_500, true], [null, null], [260_000, true]]]);
    assert.deepEqual([oddEntry.comparison!.unknownLocalDurations, ranked.disclosure.unknownLocalDurations], [1, 1]);
    assert.equal(rankLookupCandidates([candidate(standard)], odd).disclosure.unknownLocalDurations, 0, 'an import counts only a missing duration, as before');
});

test('members no audio track can pair with are named only for a release within the expected-tracklist bound', () => {
    const lengths = (count: number) => Array.from({ length: count }, (_unused, index) => 100_000 + index * 5000);
    const within = synthetic(190, [{ lengths: lengths(100) }]), beyond = synthetic(191, [{ lengths: lengths(101) }]);
    const ranked = subset([candidate(within), candidate(beyond)], [file(0, 100_000), file(1, 5_000_000)]);
    assert.deepEqual([entryOf(ranked, within).comparison!.differences, entryOf(ranked, within).comparison!.subset!.unpairableSlotIds], [['pairing'], ['slot-01']]);
    assert.deepEqual([entryOf(ranked, beyond).comparison!.differences, entryOf(ranked, beyond).comparison!.subset!.unpairableSlotIds], [['tooManyTracks'], []]);
});

test('an iTunes-only candidate never shares a subset group with a MusicBrainz one, and is preselected only when MusicBrainz ruled it out or stayed unavailable', () => {
    // Equal values under both sources: a credit without MusicBrainz IDs, so proposals, rows, pairs and track entries all agree.
    const ensemble: LookupArtistCredit = { name: 'Synthetic Ensemble', joinPhrase: '', artistId: '', artistName: 'Synthetic Ensemble' };
    const values = synthetic(160, [{ lengths: deluxe.media[0].tracks.map(track => track.lengthMs), credits: Array.from({ length: 5 }, () => 'release' as const) }],
        { artistCredit: [ensemble] });
    const itunes = (itunesCheck?: LookupCandidate['itunesCheck']): LookupCandidate => ({ key: 'itunes:1689358563', source: 'itunes', releaseId: '1689358563',
        ...(itunesCheck ? { itunesCheck } : {}), summary: null, release: { ...values, releaseId: '1689358563' } });
    const mixed = subset([candidate(values), itunes('noRelease')], threeMembers);
    assert.deepEqual([mixed.groups.length, mixed.preselection], [2, null]);
    assert.deepEqual(mixed.groups[0].proposal, mixed.groups[1].proposal, 'the proposals are equal');
    const alone = subset([itunes('noRelease')], threeMembers);
    assert.deepEqual(alone.preselection, { candidateKey: 'itunes:1689358563', groupKey: alone.groups[0].groupKey, basis: 'onlyMatchingGroup', artistMismatch: false });
    const unavailable = subset([itunes('unavailable')], threeMembers);
    assert.deepEqual([unavailable.preselection?.basis, unavailable.preselection?.notChecked], ['onlyMatchingGroup', true]);
    for (const check of ['notRun', undefined] as const) assert.deepEqual([subset([itunes(check)], threeMembers).groups.length, subset([itunes(check)], threeMembers).preselection], [1, null], String(check));
    // An exact-count iTunes-only candidate that MusicBrainz ruled out is preferred over a matching deluxe group like any other.
    const exact = subset([candidate(deluxe), { ...itunes('noRelease'), release: { ...standard, releaseId: '1689358563' } }], threeMembers);
    assert.deepEqual([exact.preselection?.candidateKey, exact.preselection?.basis], ['itunes:1689358563', 'exactTrackCount']);
});

test('in subset mode the members\' artist names flag a preselection whose credited artist agrees with none, as an import\'s tags do', () => {
    const named = (artistTags: string[]) => threeMembers.map(one => ({ ...one, artistTags }));
    const agreeing = subset([candidate(standard)], named([' synthetic LEAD ']));
    assert.deepEqual([agreeing.preselection?.basis, agreeing.preselection?.artistMismatch, entryOf(agreeing, standard).artistMismatch], ['exactTrackCount', false, false]);
    const stranger = subset([candidate(standard)], named(['Synthetic Stranger']));
    assert.deepEqual([stranger.preselection?.basis, stranger.preselection?.artistMismatch, entryOf(stranger, standard).artistMismatch], ['exactTrackCount', true, true]);
    // An alias the run found for the credited artist agrees, and members without names flag nothing.
    assert.equal(subset([candidate(standard)], named(['Synthetic Alias']), { aliases: new Map([[lead.artistId, ['Synthetic Alias']]]) }).preselection?.artistMismatch, false);
    assert.equal(subset([candidate(standard)], threeMembers).preselection?.artistMismatch, false);
});

test('the admission helpers accept an unknown count or at least the member count, and rank the fewest extra tracks first', () => {
    for (const unknown of [undefined, null, -1, 1.5, '9', Number.NaN, 2 ** 53]) assert.equal(lookupSubsetTrackCountPlausible(unknown, 3), true, String(unknown));
    assert.deepEqual([3, 5, 2].map(count => lookupSubsetTrackCountPlausible(count, 3)), [true, true, false]);
    assert.equal(lookupSubsetTrackCountPlausible(1, 0), true);
    // A known count of 0 (no audio track) can match no Album, not even one without members.
    assert.deepEqual([lookupSubsetTrackCountPlausible(0, 3), lookupSubsetTrackCountPlausible(0, 0), lookupSurplusRank(0, 0)], [false, false, Number.MAX_SAFE_INTEGER]);
    assert.deepEqual([3, 5, null, 2].map(count => lookupSurplusRank(count, 3)), [0, 2, Number.MAX_SAFE_INTEGER - 1, Number.MAX_SAFE_INTEGER]);
    const found = [2, null, 0, 5, 3, 4, 9].map((count, index) => ({ index, count }));
    assert.deepEqual([...found].sort((left, right) => lookupSurplusRank(left.count, 3) - lookupSurplusRank(right.count, 3)).map(item => item.count), [3, 4, 5, 9, null, 2, 0]);
    // Audio counts: a release's audio tracks, else a summary's audio media, else a positive total.
    const cdDvd = synthetic(130, [{ lengths: [1, 2] }, { format: 'DVD-Video', lengths: [3, 4, 5] }]);
    assert.deepEqual([
        lookupAudioTrackCount({ release: cdDvd, summary: { trackCount: 99, media: [] } as never }),
        lookupAudioTrackCount({ release: synthetic(131, [{ format: 'DVD-Video', lengths: [1] }]), trackCount: 4 }),
        lookupAudioTrackCount({ summary: { trackCount: 21, media: [{ format: 'CD', trackCount: 9 }, { format: 'Blu-ray', trackCount: 12 }] } as never }),
        lookupAudioTrackCount({ summary: { trackCount: 12, media: [{ format: 'DVD-Video', trackCount: 12 }] } as never }),
        lookupAudioTrackCount({ summary: { trackCount: 12, media: [] } as never, trackCount: 7 }),
        lookupAudioTrackCount({ summary: null, trackCount: 7, reportedTrackCount: 8 }),
        lookupAudioTrackCount({ reportedTrackCount: 8 }),
        lookupAudioTrackCount({}),
        lookupAudioTrackCount({ release: 7 as never, summary: 'x' as never, trackCount: 0, reportedTrackCount: -1 }),
        lookupAudioTrackCount({ summary: { trackCount: 12, media: [{ format: 'CD', trackCount: 0 }, { format: 'Blu-ray', trackCount: 12 }] } as never }),
        lookupAudioTrackCount({ release: synthetic(132, [{ lengths: [] }]) }),
        lookupAudioTrackCount({ summary: { trackCount: 0, media: [] } as never })
    ], [2, 0, 9, 0, 12, 7, 8, null, null, null, null, null], 'only video or data media is a known 0; an audio medium without a tracklist is unknown');
});

test('the subset assignment gives titles, numbers, durations and track artists only for a single pairing', () => {
    const credited = synthetic(140, [{ lengths: [200_000, 230_000, 260_000, 290_000], titles: [' First ', 'Second', 'Third', 'Fourth'],
        credits: [[{ ...lead, joinPhrase: ' feat. ' }, guest], undefined, [various], 'release'] }]);
    // Ordered as the ranking orders members: by own Track Number, unknown last, then upload order.
    assert.deepEqual(lookupSubsetAssignment(credited, [file(0, 230_000), file(1, 200_000), file(2, 290_000, { trackNumber: 4 })]), [
        { slotId: 'slot-02', discNumber: 1, trackNumber: 4, title: 'Fourth', durationMs: 290_000,
            artists: { artists: [{ name: 'Synthetic Lead', role: 'primary', joinPhrase: null, musicBrainzId: lead.artistId }] } },
        { slotId: 'slot-00', discNumber: 1, trackNumber: 2, title: 'Second', durationMs: 230_000, artists: { reason: 'missing' } },
        { slotId: 'slot-01', discNumber: 1, trackNumber: 1, title: 'First', durationMs: 200_000, artists: { artists: [
            { name: 'Synthetic Lead', role: 'primary', joinPhrase: ' feat. ', musicBrainzId: lead.artistId },
            { name: 'Synthetic Guest', role: 'featured', joinPhrase: null, musicBrainzId: guest.artistId }] } }]);
    assert.equal(lookupSubsetAssignment(credited, [file(0, null), file(1, null)]), null, 'several pairings');
    assert.equal(lookupSubsetAssignment(credited, files([1, 2, 3, 4, 5])), null, 'no pairing');
    const box = synthetic(141, [{ lengths: Array.from({ length: 150 }, () => 200_000) }]);
    assert.equal(lookupSubsetAssignment(box, [file(0, 200_000, { trackNumber: 1 })]), null, 'no expected tracklist');
    // An iTunes-only track gives its song's single artist string as one primary entry.
    const itunes = itunesRelease({ collectionId: '1689358563', collectionName: 'Synthetic Album', artistName: 'Synthetic Ensemble', trackCount: 2,
        releaseDate: { year: 2022, month: 8, day: 17 }, country: 'JPN', artworkUrl: null }, ['Synthetic A feat. Synthetic B', 'Synthetic Ensemble'].map((artistName, index) =>
        ({ trackId: `9${index}`, collectionId: '1689358563', collectionName: null, trackName: `Song ${index + 1}`, artistName, discNumber: 1, discCount: 1, trackNumber: index + 1,
            trackTimeMillis: 200_000 + index * 30_000 })), null);
    assert.deepEqual(lookupSubsetAssignment(itunes, [file(0, 200_000)])!.map(item => item.artists),
        [{ artists: [{ name: 'Synthetic A feat. Synthetic B', role: 'primary', joinPhrase: null, musicBrainzId: null }] }]);
});

test('track credits: a featuring phrase makes the following entries featured, repeats and placeholders are dropped, and MusicBrainz IDs are kept', () => {
    const release = { artistCredit: [lead] };
    const credit: LookupArtistCredit[] = [{ ...lead, joinPhrase: ' feat. ' }, { ...guest, joinPhrase: ' & ' }, { name: 'Synthetic Third', joinPhrase: ', ', artistId: mbid(902), artistName: 'Synthetic Third' },
        { name: 'SYNTHETIC LEAD', joinPhrase: ', ', artistId: mbid(903), artistName: 'Other' }, { ...guest, name: 'Guest Alias', joinPhrase: ', ' }, various];
    assert.deepEqual(trackArtistProposal(release, { artistCredit: credit }), { artists: [
        { name: 'Synthetic Lead', role: 'primary', joinPhrase: ' feat. ', musicBrainzId: lead.artistId },
        { name: 'Synthetic Guest', role: 'featured', joinPhrase: ' & ', musicBrainzId: guest.artistId },
        { name: 'Synthetic Third', role: 'featured', joinPhrase: ', ', musicBrainzId: mbid(902) }] });
    // The marker reads as the release credit; it never falls back to the release credit otherwise.
    assert.deepEqual(trackArtistProposal(release, { artistCredit: 'release' }), { artists: [{ name: 'Synthetic Lead', role: 'primary', joinPhrase: null, musicBrainzId: lead.artistId }] });
    assert.deepEqual(lookupTrackCredit(release, { artistCredit: 'release' }), [lead]);
});

test('track credits: a placeholder-only credit gives placeholder, and an absent or malformed credit gives missing', () => {
    const release = { artistCredit: [lead] };
    const unknownArtist: LookupArtistCredit = { name: '[unknown]', joinPhrase: '', artistId: '125ec42a-7229-4250-afc5-e057484327fe', artistName: '[unknown]' };
    assert.deepEqual([trackArtistProposal(release, { artistCredit: [various] }), trackArtistProposal(release, { artistCredit: [various, unknownArtist] })],
        [{ reason: 'placeholder' }, { reason: 'placeholder' }]);
    assert.deepEqual([trackArtistProposal(release, { artistCredit: [] }), lookupTrackCredit(release, { artistCredit: [] })], [{ reason: 'missing' }, []]);
    for (const track of [{}, { artistCredit: 'other' }, { artistCredit: [{ name: 7 }] }, { artistCredit: [null] }, { artistCredit: { name: 'x' } }, null]) {
        assert.deepEqual(trackArtistProposal(release, track as never), { reason: 'missing' }, JSON.stringify(track));
        assert.equal(lookupTrackCredit(release, track as never), null, JSON.stringify(track));
    }
    for (const broken of [{ artistCredit: 'x' }, { artistCredit: [{ name: 'x' }] }, null]) {
        assert.deepEqual(trackArtistProposal(broken as never, { artistCredit: 'release' }), { reason: 'missing' }, JSON.stringify(broken));
    }
    // An empty name is no credit: an iTunes song with an empty artist string is stored as this one entry.
    const empty: LookupArtistCredit = { name: '', joinPhrase: '', artistId: '', artistName: '' };
    assert.deepEqual([trackArtistProposal(release, { artistCredit: [empty] }), trackArtistProposal(release, { artistCredit: [{ ...empty, name: '   ' }, empty] })],
        [{ reason: 'missing' }, { reason: 'missing' }]);
    assert.deepEqual(trackArtistProposal(release, { artistCredit: [empty, various] }), { reason: 'placeholder' });
    assert.deepEqual(trackArtistProposal(release, { artistCredit: [empty, guest] }), { artists: [{ name: 'Synthetic Guest', role: 'primary', joinPhrase: null, musicBrainzId: guest.artistId }] });
});

test('two candidates differing only in a paired track\'s credit form two groups, while a difference in an unpaired track\'s credit does not split a group', () => {
    const credits = (first: MusicBrainzTrack['artistCredit'], last: MusicBrainzTrack['artistCredit']) => [first, 'release', 'release', 'release', last] as MusicBrainzTrack['artistCredit'][];
    const base = synthetic(150, [{ lengths: deluxe.media[0].tracks.map(track => track.lengthMs), credits: credits('release', 'release') }]);
    const pairedGuest = synthetic(151, [{ lengths: deluxe.media[0].tracks.map(track => track.lengthMs), credits: credits([guest], 'release') }]);
    const unpairedGuest = synthetic(152, [{ lengths: deluxe.media[0].tracks.map(track => track.lengthMs), credits: credits('release', [guest]) }]);
    const ranked = subset([candidate(base), candidate(pairedGuest), candidate(unpairedGuest)], threeMembers);
    assert.deepEqual([ranked.groups.length, ranked.preselection], [2, null]);
    assert.equal(entryOf(ranked, base).groupKey, entryOf(ranked, unpairedGuest).groupKey);
    assert.notEqual(entryOf(ranked, base).groupKey, entryOf(ranked, pairedGuest).groupKey);
    // A track credit equal to the release's groups with its marker.
    const spelledOut = synthetic(153, [{ lengths: deluxe.media[0].tracks.map(track => track.lengthMs), credits: credits([lead], 'release') }]);
    assert.equal(entryOf(subset([candidate(base), candidate(spelledOut)], threeMembers), spelledOut).groupKey, entryOf(ranked, base).groupKey);
    // The exact import comparison ignores track credits.
    const exact = rankLookupCandidates([candidate(base), candidate(pairedGuest)], files(deluxe.media[0].tracks.map(track => track.lengthMs)));
    assert.equal(exact.groups.length, 1);
});

test('stored track credits of an unknown shape propose nothing for their members and group like tracks without credits, never throwing', () => {
    const lengths = standard.media[0].tracks.map(track => track.lengthMs);
    const malformed = synthetic(180, [{ lengths, credits: ['other' as never, [{ name: 7 }] as never, 'release'] }]);
    const absent = synthetic(181, [{ lengths, credits: [undefined, undefined, 'release'] }]);
    const ranked = subset([candidate(malformed), candidate(absent)], threeMembers);
    assert.deepEqual([ranked.groups.length, ranked.groups[0].memberKeys.length, ranked.preselection?.basis], [1, 2, 'exactTrackCount']);
    assert.deepEqual(lookupSubsetAssignment(malformed, threeMembers)!.map(item => item.artists), [{ reason: 'missing' }, { reason: 'missing' },
        { artists: [{ name: 'Synthetic Lead', role: 'primary', joinPhrase: null, musicBrainzId: lead.artistId }] }]);
});
